<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>LBFP Owner Dashboard</title><link rel="icon" href="https://raw.githubusercontent.com/rath0darya/LBFP/main/temp/AppIcon.png"><link rel="stylesheet" href="owner.css"></head><body><main class="wrap"><section id="login" class="panel login"><img src="https://raw.githubusercontent.com/rath0darya/LBFP/main/temp/AppIcon.png" alt="LBFP" class="logo"><p class="eyebrow">LADDU BHAI FOOD POINT</p><h1>Owner sign in</h1><form id="login-form"><label>Username<input name="username" autocomplete="username" maxlength="80" required></label><label>Password<input name="password" type="password" autocomplete="current-password" required maxlength="200"></label><p id="login-msg" class="msg"></p><button>Sign in</button></form></section><section id="app" hidden><header><div><p class="eyebrow">RESTAURANT CONTROL</p><h1>Owner dashboard</h1></div><button id="logout" class="light">Sign out</button></header><div class="stats"><article><small>Active orders</small><b id="active">—</b></article><article><small>Today's orders</small><b id="count">—</b></article><article><small>Today's sales</small><b id="sales">—</b></article><article><small>Available dishes</small><b id="available">—</b></article></div><nav><button class="tab active" data-tab="orders">Orders</button><button class="tab light" data-tab="menu">Menu management</button><button id="refresh" class="light">Refresh orders</button></nav><section id="orders" class="panel"><h2>Incoming orders</h2><p id="orders-msg" class="msg"></p><div id="orders-list"></div></section><section id="menu" class="panel" hidden><div class="between"><h2>Menu management</h2><button id="add">+ Add dish</button></div><p id="menu-msg" class="msg"></p><div id="menu-list"></div><form id="dish-form" hidden><h3 id="form-title">Add dish</h3><input name="id" type="hidden"><div class="fields"><label>Dish name<input name="name" required maxlength="140"></label><label>Serving variant<input name="variant" required maxlength="30" value="Single" placeholder="Single / Plate"></label><label>Category<input name="category" required maxlength="50"></label><label>Price ₹<input name="price" type="number" min=".01" max="999999" step=".01" required></label><label>Emoji<input name="emoji" maxlength="20" value="🍽️"></label><label class="wide">Description<textarea name="description" maxlength="500"></textarea></label><label>Sort order<input name="sort_order" type="number" min="0" value="100"></label></div><button>Save dish</button> <button type="button" id="cancel" class="light">Cancel</button></form></section><footer>Customer storefront: <a href="../">open website</a></footer></section></main><script src="owner.js" defer></script></body></html>